use verus::prelude::*;

// Specification for `empty`:
//
//   requires:  nothing (we accept any `n: u8`)
//   ensures:   the returned Vec<f64> has length exactly `n`
//              and every element is 0.0
#[requires(true)]
#[ensures(|res: &Vec<f64>| res.len() == n as usize
               && forall(|i: usize| i < res.len() ==> res[i] == 0.0))]
fn empty(n: u8) -> Vec<f64> {
    // Pre-allocate exactly n elements to avoid reallocations.
    let mut result = Vec::with_capacity(n as usize);
    // Iteratively push zeros until we reach the desired length.
    //
    // Loop‐invariant: at the start of each iteration,
    //   result.len() == idx as usize
    #[invariant(result.len() == idx as usize)]
    for idx in 0..n {
        result.push(0.0);
    }
    result
}

